import ctypes
import os

def assert_test():
    # Load the required libraries in the correct order
    try:
        libgslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    except OSError as e:
        raise RuntimeError(f"Failed to load libraries: {e}")

    # Access the gsl_odeiv2_step_bsimp symbol
    try:
        gsl_odeiv2_step_bsimp = ctypes.c_void_p.in_dll(gsl, "gsl_odeiv2_step_bsimp")
    except ValueError as e:
        raise RuntimeError(f"Failed to load symbol 'gsl_odeiv2_step_bsimp': {e}")

    # Check if the symbol address is valid
    if not gsl_odeiv2_step_bsimp:
        raise RuntimeError("Symbol 'gsl_odeiv2_step_bsimp' is NULL or invalid.")

    # If everything is successful, return a success message
    print("Symbol 'gsl_odeiv2_step_bsimp' loaded successfully.")

if __name__ == "__main__":
    assert_test()
